/* Shared overlay scrollbar. Native scrolling, wheel and touch stay on the region. */
.dh-scroll-native { scrollbar-width: none; }
.dh-scroll-native::-webkit-scrollbar { display: none; }
.dh-scroll-rail {
  --dh-scroll-ink: #506255;
  position: fixed;
  z-index: var(--dh-scroll-layer, 40);
  padding: 0;
  border: 0;
  border-radius: 12px;
  background: transparent;
  opacity: 0;
  transition: opacity 180ms ease;
  touch-action: none;
  cursor: default;
  outline-offset: -2px;
}
.dh-scroll-rail[data-axis="y"] { width: 20px; }
.dh-scroll-rail[data-axis="x"] { height: 20px; }
.dh-scroll-rail.is-active, .dh-scroll-rail:hover, .dh-scroll-rail:focus-visible { opacity: 1; }
.dh-scroll-rail:focus-visible { outline: 2px solid var(--dh-scroll-ink); }
.dh-scroll-rail[hidden] { display: none; }
.dh-scroll-thumb { position: absolute; border-radius: 12px; }
.dh-scroll-rail[data-axis="y"] .dh-scroll-thumb { width: 20px; left: 0; }
